--- /dev/null
+++ b/src/component/Header.css
@@ -0,0 +1,268 @@
+/* Retro UI Navbar Styles */
+:root {
+  --retro-bg: #ffffff;
+  --retro-fg: #000000;
+  --retro-border: #000000;
+  --retro-accent: #ffda59;
+  --retro-accent-fg: #000000;
+  --retro-primary: #ff6b6b;
+  --retro-primary-fg: #ffffff;
+  --retro-secondary: #f8f9fa;
+  --retro-card: #ffffff;
+}
+
+html.dark {
+  --retro-bg: #121212;
+  --retro-fg: #ffffff;
+  --retro-border: #000000;
+  --retro-accent: #ffb703;
+  --retro-accent-fg: #000000;
+  --retro-primary: #e63946;
+  --retro-primary-fg: #ffffff;
+  --retro-secondary: #2b2b2b;
+  --retro-card: #1e1e1e;
+}
+
+.retro-header {
+  position: fixed;
+  top: 0;
+  left: 0;
+  right: 0;
+  z-index: 1000;
+  width: 100%;
+  border-bottom: 4px solid #000000;
+  background-color: var(--retro-bg);
+  box-sizing: border-box;
+  font-family: inherit;
+}
+
+.retro-container {
+  max-width: 1152px;
+  margin: 0 auto;
+  display: flex;
+  height: 80px;
+  width: 100%;
+  align-items: center;
+  justify-content: space-between;
+  gap: 16px;
+  padding: 0 16px;
+  box-sizing: border-box;
+}
+
+.retro-logo {
+  border: 4px solid #000000;
+  background-color: var(--retro-accent);
+  color: var(--retro-accent-fg) !important;
+  padding: 8px 12px;
+  font-size: 14px;
+  font-weight: 900;
+  letter-spacing: 0.025em;
+  box-shadow: 4px 4px 0px #000000;
+  text-decoration: none !important;
+  display: inline-block;
+  white-space: nowrap;
+}
+
+@media (min-width: 640px) {
+  .retro-logo {
+    font-size: 16px;
+  }
+}
+
+.retro-logo:hover,
+.retro-logo:focus {
+  text-decoration: none !important;
+  color: var(--retro-accent-fg) !important;
+}
+
+.retro-nav-desktop {
+  display: none;
+  align-items: center;
+  gap: 8px;
+}
+
+@media (min-width: 768px) {
+  .retro-nav-desktop {
+    display: flex;
+  }
+}
+
+.retro-nav-item {
+  border: 4px solid #000000;
+  padding: 8px 12px;
+  font-size: 14px;
+  font-weight: 900;
+  text-transform: uppercase;
+  letter-spacing: 0.025em;
+  box-shadow: 4px 4px 0px #000000;
+  transition: transform 0.15s ease, box-shadow 0.15s ease;
+  text-decoration: none !important;
+  display: inline-block;
+  background-color: var(--retro-card);
+  color: var(--retro-fg) !important;
+}
+
+.retro-nav-item:hover,
+.retro-nav-item:focus {
+  text-decoration: none !important;
+  transform: translate(2px, 2px);
+  box-shadow: 2px 2px 0px #000000;
+  color: var(--retro-fg) !important;
+}
+
+.retro-nav-item.active {
+  background-color: var(--retro-primary);
+  color: var(--retro-primary-fg) !important;
+}
+
+.retro-nav-item.active:hover,
+.retro-nav-item.active:focus {
+  color: var(--retro-primary-fg) !important;
+}
+
+.retro-actions {
+  display: flex;
+  align-items: center;
+  gap: 8px;
+}
+
+.retro-signin-desktop {
+  display: none;
+}
+
+@media (min-width: 768px) {
+  .retro-signin-desktop {
+    display: flex;
+    align-items: center;
+    gap: 8px;
+  }
+}
+
+.retro-btn {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  border: 4px solid #000000;
+  font-weight: 900;
+  text-transform: uppercase;
+  cursor: pointer;
+  box-shadow: 2px 2px 0px #000000;
+  transition: transform 0.15s ease, box-shadow 0.15s ease;
+  background-color: var(--retro-card);
+  color: var(--retro-fg);
+  height: 44px;
+  padding: 0 16px;
+  font-size: 14px;
+  line-height: 1;
+  text-decoration: none !important;
+}
+
+.retro-btn:hover {
+  transform: translate(2px, 2px);
+  box-shadow: none;
+}
+
+.retro-btn-icon {
+  width: 44px;
+  height: 44px;
+  padding: 0;
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+}
+
+.retro-btn-primary {
+  background-color: var(--retro-primary);
+  color: var(--retro-primary-fg);
+}
+
+.retro-btn-secondary {
+  background-color: var(--retro-secondary);
+  color: var(--retro-fg);
+}
+
+.retro-theme-toggle {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  width: 44px;
+  height: 44px;
+  border: 4px solid #000000;
+  background-color: var(--retro-card);
+  color: var(--retro-fg);
+  box-shadow: 4px 4px 0px #000000;
+  cursor: pointer;
+  transition: transform 0.15s ease, box-shadow 0.15s ease;
+}
+
+.retro-theme-toggle:hover {
+  transform: translate(2px, 2px);
+  box-shadow: 2px 2px 0px #000000;
+}
+
+.retro-mobile-toggle {
+  display: inline-flex;
+}
+
+@media (min-width: 768px) {
+  .retro-mobile-toggle {
+    display: none;
+  }
+}
+
+.retro-mobile-menu {
+  border-top: 4px solid #000000;
+  background-color: var(--retro-bg);
+  padding: 16px;
+}
+
+@media (min-width: 768px) {
+  .retro-mobile-menu {
+    display: none;
+  }
+}
+
+.retro-mobile-grid {
+  display: flex;
+  flex-direction: column;
+  gap: 8px;
+}
+
+.retro-mobile-nav-item {
+  border: 4px solid #000000;
+  padding: 8px 12px;
+  text-align: center;
+  font-size: 14px;
+  font-weight: 900;
+  text-transform: uppercase;
+  box-shadow: 4px 4px 0px #000000;
+  text-decoration: none !important;
+  background-color: var(--retro-card);
+  color: var(--retro-fg) !important;
+  display: block;
+}
+
+.retro-mobile-nav-item.active {
+  background-color: var(--retro-primary);
+  color: var(--retro-primary-fg) !important;
+}
+
+.retro-avatar {
+  width: 40px;
+  height: 40px;
+  border: 4px solid #000000;
+  border-radius: 50%;
+  box-shadow: 2px 2px 0px #000000;
+  background-color: var(--retro-primary);
+  color: var(--retro-primary-fg);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-weight: 900;
+  font-size: 12px;
+  overflow: hidden;
+}
+
+body {
+  padding-top: 80px;
+}

