--- /dev/null
+++ b/src/component/Avatar.js
@@ -0,0 +1,31 @@
+import React from "react";
+
+const AvatarRoot = React.forwardRef(({ className = "", children, ...props }, ref) => (
+  <div ref={ref} className={`retro-avatar-root ${className}`} {...props}>
+    {children}
+  </div>
+));
+AvatarRoot.displayName = "Avatar";
+
+const AvatarImage = React.forwardRef(({ className = "", src, alt, ...props }, ref) => (
+  <img
+    ref={ref}
+    src={src}
+    alt={alt || "Avatar"}
+    className={`retro-avatar-img ${className}`}
+    {...props}
+  />
+));
+AvatarImage.displayName = "Avatar.Image";
+
+const AvatarFallback = React.forwardRef(({ className = "", children, ...props }, ref) => (
+  <div ref={ref} className={`retro-avatar-fallback ${className}`} {...props}>
+    {children}
+  </div>
+));
+AvatarFallback.displayName = "Avatar.Fallback";
+
+export const Avatar = Object.assign(AvatarRoot, {
+  Image: AvatarImage,
+  Fallback: AvatarFallback,
+});

