+++ b/src/component/Button.js
@@ -0,0 +1,36 @@
+import React from "react";
+
+export const Button = React.forwardRef(
+  (
+    {
+      children,
+      size = "md",
+      className = "",
+      variant = "default",
+      type = "button",
+      ...props
+    },
+    ref
+  ) => {
+    const baseClass = "retro-btn";
+    const variantClass =
+      variant === "secondary"
+        ? "retro-btn-secondary"
+        : variant === "outline"
+        ? "retro-btn-outline"
+        : "retro-btn-default";
+
+    return (
+      <button
+        ref={ref}
+        type={type}
+        className={`${baseClass} ${variantClass} ${className}`}
+        {...props}
+      >
+        {children}
+      </button>
+    );
+  }
+);
+
+Button.displayName = "Button";

