+import { Avatar } from "./Avatar";
+import { Button } from "./Button";
+import { Github, LogOut } from "./icons";
+
+export function SignInButton({ className = "" }) {
+  const [sessionUser, setSessionUser] = useState(null);
+
+  const handleSignIn = () => {
+    setSessionUser({
+      name: "Muhammad Fiaz",
+      email: "contact@muhammadfiaz.com",
+      image: null,
+    });
+  };
+
+  const handleSignOut = () => {
+    setSessionUser(null);
+  };
+
+  if (sessionUser) {
+    const initialsSource =
+      sessionUser.name?.trim() || sessionUser.email?.trim() || "Muhammad Fiaz";
+    const initials = initialsSource
+      .split(/\s+/)
+      .filter(Boolean)
+      .slice(0, 2)
+      .map((part) => part[0]?.toUpperCase() ?? "")
+      .join("");
+    const avatarSrc = sessionUser.image ?? undefined;
+
+    return (
+      <div className="retro-signin-user">
+        <Avatar className="retro-avatar-root">
+          {avatarSrc ? (
+            <Avatar.Image src={avatarSrc} alt={sessionUser.name ?? "User"} />
