+import React from 'react';
+import { Link as RouterLink } from 'react-router-dom';
+
+const CustomLink = ({ href, children, className = '', onClick, ...rest }) => {
+  const isInternalLink = href && href.startsWith('/') && !href.startsWith('//');
+  const isAnchorLink = href && href.startsWith('#');
+
+  if (isInternalLink) {
+    return (
+      <RouterLink className={`break-words ${className}`} to={href} onClick={onClick} {...rest}>
+        {children}
+      </RouterLink>
+    );
+  }
+
+  if (isAnchorLink) {
+    return (
+      <a className={`break-words ${className}`} href={href} onClick={onClick} {...rest}>
+        {children}
+      </a>
+    );
+  }
+
+  return (
+    <a
+      className={`break-words ${className}`}
+      target="_blank"
+      rel="noopener noreferrer"
+      href={href}
+      onClick={onClick}
+      {...rest}
+    >
+      {children}
+    </a>
+  );
+};
+
+export default CustomLink;

